publicity_type = #{p.publicityType}, title = #{p.title}, content = #{p.content}, start_date = #{p.startDate}, end_date = #{p.endDate}, contact_email = #{p.contactEmail}, publish_user_id = #{p.publishUserId}, updated_at = NOW()
